import tables from './artifact-tables.mjs';
export const slots=['Flower','Feather','Sands','Goblet','Circlet'];
export const subKeys=Object.keys(tables.sub[5]);
export const maxLevel=r=>({1:4,2:4,3:12,4:16,5:20})[r]||20;
export const mainKeys=i=>i===0?['hpFlat']:i===1?['atkFlat']:i===2?['hpPct','atkPct','defPct','em','er']:i===3?['hpPct','atkPct','defPct','em','pyroDmg','cryoDmg','hydroDmg','anemoDmg','electroDmg','geoDmg','dendroDmg','physicalDmg']:['hpPct','atkPct','defPct','em','cr','cd','heal'];
export const rolls=(a,key)=>tables.sub[a.rarity||5][key]||[];
export const mainValue=a=>tables.main[a.rarity||5][a.main.stat]?.[a.level];
export function applyMain(a,i){a.rarity=Number(a.rarity)||5;a.level=Math.min(maxLevel(a.rarity),Math.max(0,Math.floor(a.level)));if(!mainKeys(i).includes(a.main.stat))a.main.stat=mainKeys(i)[0];a.main.value=mainValue(a);}
export function possibleRollCounts(a,s){if(!s.value)return [0];let sums=new Set([0]),out=[];const tolerance=['hpFlat','atkFlat','defFlat','em'].includes(s.stat)?0.51:0.055;for(let n=1;n<=1+Math.floor(a.level/4);n++){const next=new Set();for(const v of sums)for(const r of rolls(a,s.stat))next.add(Math.round((v+r)*1e5)/1e5);sums=next;if([...sums].some(v=>Math.abs(v-s.value)<=tolerance))out.push(n)}return out}
export function artifactIssues(a,i){const issues=[],seen=new Set(),rank=a.rarity||5;if(!mainKeys(i).includes(a.main.stat))issues.push('Main stat is not valid for this slot.');if(a.level>maxLevel(rank))issues.push('Level exceeds the rarity limit.');if(mainValue(a)!==undefined&&Math.abs(a.main.value-mainValue(a))>0.55)issues.push('Main value does not match this level. Apply the level table.');let minRolls=0;for(const s of a.subs){if(!s.value)continue;if(!subKeys.includes(s.stat)||s.stat===a.main.stat||seen.has(s.stat))issues.push('Substats must be unique and different from the main stat.');seen.add(s.stat);const counts=possibleRollCounts(a,s);if(!counts.length)issues.push('A substat value cannot be formed from legal rolls at this level.');else minRolls+=Math.min(...counts)}const budget=Math.min(4,rank-1)+Math.floor(a.level/4);if(minRolls>budget)issues.push('Total substat rolls exceed the level’s roll budget.');return [...new Set(issues)]}
export function addRoll(a,j,tier){const s=a.subs[j],v=rolls(a,s.stat)[tier];if(v===undefined||!s.stat||s.stat===a.main.stat||a.subs.some((x,k)=>k!==j&&x.value&&x.stat===s.stat))return false;const nextValue=Math.round(((Number(s.value)||0)+v)*1e5)/1e5,next={...a,subs:a.subs.map((x,k)=>k===j?{...x,value:nextValue}:x)};if(!possibleRollCounts(next,next.subs[j]).length)return false;const used=next.subs.filter((x,k)=>x.value&&k!==j&&possibleRollCounts(next,x).length).reduce((sum,x)=>sum+Math.min(...possibleRollCounts(next,x)),0);const budget=Math.min(4,(next.rarity||5)-1)+Math.floor(next.level/4);if(used+Math.min(...possibleRollCounts(next,next.subs[j]))>budget)return false;s.value=nextValue;return true}
